# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HİKÂYE YAZMA SÜRECİ, ANLATIM TEKNİKLERİ VE TEMSİLCİLERİ</text>\n  <!-- Sol: Yazma Asamalari ve Teknikler -->\n  <rect x="25" y="42" width="320" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KURGU PLANI VE ANLATIM TEKNİKLERİ</text>\n  <rect x="40" y="78" width="290" height="44" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="185" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">Yapı Unsurları ve Bakış Açısı</text>\n  <text x="185" y="113" text-anchor="middle" font-size="10.8" fill="#1d4ed8">Olay örgüsü, Kişiler, Mekân, Zaman | İlahi / Kahraman / Gözlemci</text>\n  <text x="40" y="142" font-size="11.2" fill="#1e3a8a">• <tspan font-weight="bold">Geriye Dönüş:</tspan> Karakterin geçmişini hatırlaması.</text>\n  <text x="40" y="162" font-size="11.2" fill="#1e3a8a">• <tspan font-weight="bold">İç Konuşma:</tspan> Düzenli cümlelerle içsel diyalog.</text>\n  <text x="40" y="182" font-size="11.2" fill="#1e3a8a">• <tspan font-weight="bold">Bilinç Akışı:</tspan> Serbest çağrışımlı, kopuk düşünceler.</text>\n  <text x="40" y="202" font-size="11.2" fill="#1e3a8a">• <tspan font-weight="bold">Gösterme / Diyalog:</tspan> Olayı okura canlandırma.</text>\n  <text x="40" y="222" font-size="11.2" font-weight="bold" fill="#1d4ed8">• <tspan font-weight="bold">Üst Kurmaca:</tspan> Yazma sürecini metne dahil etme.</text>\n  <!-- Sag: Yazar-Eser -->\n  <rect x="365" y="42" width="310" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">MODERN HİKÂYENİN ÖNCÜ YAZARLARI</text>\n  <text x="380" y="90" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Oğuz Atay:</tspan> Korkuyu Beklerken</text>\n  <text x="380" y="110" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Ferit Edgü:</tspan> Kaçkınlar, Bir Gemide, Çığlık</text>\n  <text x="380" y="130" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Sevim Burak:</tspan> Yanık Saraylar, Afrika Dansı</text>\n  <text x="380" y="150" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Rasim Özdenören:</tspan> Hastalar ve Işıklar, Çözülme</text>\n  <text x="380" y="170" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Tomris Uyar:</tspan> İpek ve Bakır, Yürekte Bukağı</text>\n  <text x="380" y="190" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Nezihe Meriç:</tspan> Bozbulanık, Menekşeli Bilinç</text>\n  <text x="380" y="210" font-size="11.2" fill="#78350f">• <tspan font-weight="bold">Orhan Duru:</tspan> Ağır İşçiler, Sarmal ("Bilim kurgu")</text>\n  <text x="520" y="232" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#b45309">Bireyin iç dünyası ve varoluşçu temalar işlenmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KÜÇÜREK (MİNİMAL) HİKÂYE KURGULAMA İLKELERİ</text>\n  <!-- Sol: Kurgulama İlkeleri -->\n  <rect x="25" y="42" width="325" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="187" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">KÜÇÜREK HİKÂYENİN 5 TEMEL ÖZELLİĞİ</text>\n  <text x="40" y="92" font-size="11.5" fill="#14532d">1. <tspan font-weight="bold">Kısalık ve Yoğunluk:</tspan> Az sözle derin anlam.</text>\n  <text x="40" y="116" font-size="11.5" fill="#14532d">2. <tspan font-weight="bold">Betimleme Azlığı:</tspan> Uzun kişi/mekân tasviri yoktur.</text>\n  <text x="40" y="140" font-size="11.5" fill="#14532d">3. <tspan font-weight="bold">Kesit Yapısı:</tspan> Klasik serim-düğüm-çözüm bulunmaz.</text>\n  <text x="40" y="164" font-size="11.5" fill="#14532d">4. <tspan font-weight="bold">Şiirsellik ve İmge:</tspan> Sembol, alegori ve ironi gücü.</text>\n  <text x="40" y="188" font-size="11.5" fill="#14532d">5. <tspan font-weight="bold">Aktif Okur (Açık Uçluluk):</tspan> Anlam boşluklarını</text>\n  <text x="54" y="206" font-size="11.5" fill="#14532d">ve hikâyenin öncesi-sonrasını okur tamamlar.</text>\n  <text x="187" y="230" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Temsilciler: Ferit Edgü, Hulki Aktunç, Necati Tosuner</text>\n  <!-- Sag: Ornek Analiz -->\n  <rect x="370" y="42" width="305" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="522" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">KÜÇÜREK KURGU MODELİ</text>\n  <rect x="388" y="80" width="270" height="52" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="523" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">1. Çarpıcı Başlangıç (Doğrudan Olaya Giriş)</text>\n  <text x="523" y="116" text-anchor="middle" font-size="10.8" fill="#6b21a8">Hazırlık yapmadan tezat veya çatışma anını verme</text>\n  <rect x="388" y="140" width="270" height="44" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="523" y="158" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">2. Sembolik veya İronik Düğüm</text>\n  <text x="523" y="174" text-anchor="middle" font-size="10.8" fill="#6b21a8">Gereksiz her sözcüğü atarak anlamı yoğunlaştırma</text>\n  <rect x="388" y="192" width="270" height="40" rx="6" fill="#ffffff" stroke="#9333ea"/>\n  <text x="523" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">3. Vurucu / Şaşırtıcı Bitiş Cümlesi</text>\n  <text x="523" y="225" text-anchor="middle" font-size="10.5" fill="#581c87">(Örnek: Salih Bolat - "Doktora Tezi" öyküsü)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÖZLÜ İLETİŞİM: DRAMATİZASYON VE ETKİLİ SUNUM İLKELERİ</text>\n  <!-- Sol: Dramatizasyon -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">HİKÂYEYİ DRAMATİZE ETME</text>\n  <rect x="42" y="78" width="280" height="42" rx="6" fill="#ffedd5" stroke="#f97316"/>\n  <text x="182" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7c2d12">Anlatma Dilinden → Gösterme (Sahne) Diline</text>\n  <text x="182" y="112" text-anchor="middle" font-size="10.8" fill="#9a3412">Öyküyü diyalog ve hareketle canlandırma</text>\n  <text x="42" y="142" font-size="11.5" fill="#7c2d12">• Hikâyedeki olay örgüsü sahnelere bölünür.</text>\n  <text x="42" y="164" font-size="11.5" fill="#7c2d12">• Betimlemeler dekor ve sahne yönergesine dönüşür.</text>\n  <text x="42" y="186" font-size="11.5" fill="#7c2d12">• Gösterme yöntemi ve doğaçlama kullanılır.</text>\n  <text x="42" y="208" font-size="11.5" font-weight="bold" fill="#c2410c">• Yapmacıklıktan uzak, doğal davranışlar</text>\n  <text x="52" y="224" font-size="11.5" font-weight="bold" fill="#c2410c">ve karaktere uygun ses tonu esastır.</text>\n  <!-- Sag: Sunum İlkeleri -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">ETKİLİ SUNUM VE KONUŞMA İLKELERİ</text>\n  <text x="378" y="92" font-size="11.5" fill="#7f1d1d">✓ İlgi çekici başlangıç ve özlü kapanış yapmak.</text>\n  <text x="378" y="114" font-size="11.5" fill="#7f1d1d">✓ Dinleyicilerle sürekli göz teması kurmak.</text>\n  <text x="378" y="136" font-size="11.5" fill="#7f1d1d">✓ Vurgu, tonlama ve beden dilini doğru kullanmak.</text>\n  <text x="378" y="158" font-size="11.5" fill="#7f1d1d">✓ "Iıı, eee, şey" gibi gereksiz seslerden kaçınmak.</text>\n  <text x="378" y="180" font-size="11.5" fill="#7f1d1d">✓ Süreyi ve görsel materyalleri verimli yönetmek.</text>\n  <rect x="378" y="194" width="280" height="38" rx="6" fill="#fee2e2"/>\n  <text x="518" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Dinleyici Sorumluluğu: Empatik dinleme,</text>\n  <text x="518" y="226" text-anchor="middle" font-size="11" fill="#7f1d1d">anahtar kavramları not alma ve soru sorma.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
